-- Copart + IAAI sale results in one read-only view (same columns in both
-- tables). Prisma does not create views: this file is the source of truth.
CREATE OR REPLACE VIEW "sale_results_all" AS
  SELECT 'copart'::text AS "auction", "id","lot","saleDate","auctionSession","saleLocationSlug","finalBid","askingPrice","reserve","sold","ticks","round","saleOrder","event","pageUrl","receivedAt","saleRoom","reserveMet","approved","buyerNo","buyerState","buyerCountry","itemNo","emittedAt","pendingApproval","matched","vin","year","make","model","modelDetail","trim","bodyStyle","color","damageDescription","secondaryDamage","saleTitleType","saleTitleState","odometer","runsDrives","engine","transmission","drive","fuelType","cylinders","estRetailValue","repairCost","highBidAtSync","yardNumber","yardName","locationCity","locationState","locationZip","sellerName","sellerCategory","vehicleSnapshot","raw","createdAt","updatedAt" FROM "auction_sale_results"
  UNION ALL
  SELECT 'iaai'::text AS "auction", "id","lot","saleDate","auctionSession","saleLocationSlug","finalBid","askingPrice","reserve","sold","ticks","round","saleOrder","event","pageUrl","receivedAt","saleRoom","reserveMet","approved","buyerNo","buyerState","buyerCountry","itemNo","emittedAt","pendingApproval","matched","vin","year","make","model","modelDetail","trim","bodyStyle","color","damageDescription","secondaryDamage","saleTitleType","saleTitleState","odometer","runsDrives","engine","transmission","drive","fuelType","cylinders","estRetailValue","repairCost","highBidAtSync","yardNumber","yardName","locationCity","locationState","locationZip","sellerName","sellerCategory","vehicleSnapshot","raw","createdAt","updatedAt" FROM "iaai_sale_results";
